CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),profile_photo TEXT,status TEXT DEFAULT 'Offline');
CREATE TABLE IF NOT EXISTS doctors (id TEXT PRIMARY KEY,account_id TEXT REFERENCES accounts(id) ON DELETE CASCADE,first_name TEXT NOT NULL,last_name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY,account_id TEXT REFERENCES accounts(id) ON DELETE CASCADE,first_name TEXT NOT NULL,last_name TEXT NOT NULL,age INTEGER NOT NULL DEFAULT 0,gender TEXT,primary_doctor_id TEXT REFERENCES doctors(id) ON DELETE SET NULL,device_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL,mqtt_broker TEXT,mqtt_port INTEGER,mqtt_topic TEXT,mqtt_username TEXT,mqtt_password TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),patient_id TEXT NOT NULL REFERENCES patients(id),started_at TIMESTAMPTZ NOT NULL,ended_at TIMESTAMPTZ,file_path TEXT,ecg_paper TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS frame_records (id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,start_time DOUBLE PRECISION NOT NULL,end_time DOUBLE PRECISION NOT NULL,time_interval TEXT NOT NULL,label TEXT NOT NULL,dev_note TEXT,doc_note TEXT,confirmation BOOLEAN,doc_classification TEXT,hidden BOOLEAN NOT NULL DEFAULT false,created_by TEXT REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
